1352	+export class ProductDetail {
1353	+  private readonly productsApi = inject(ProductsApi);
1354	+
1355	+  readonly id = input.required<string>();
1356	+
1357	+  protected readonly product = signal<ProductDetailModel | null>(null);
1358	+  protected readonly loading = signal(false);
1359	+  protected readonly notFound = signal(false);
1360	+  protected readonly error = signal(false);
1361	+
1362	+  constructor() {
1363	+    effect(() => {
1364	+      const id = this.id();
1365	+      this.loading.set(true);
1366	+      this.notFound.set(false);
1367	+      this.error.set(false);
1368	+
1369	+      this.productsApi.getProduct(id).subscribe({
1370	+        next: (product) => {
1371	+          if (this.id() !== id) {
1372	+            return;
1373	+          }
1374	+          this.product.set(product);
1375	+          this.loading.set(false);
1376	+        },
1377	+        error: (err) => {
1378	+          if (this.id() !== id) {
1379	+            return;
1380	+          }
1381	+          this.loading.set(false);
1382	+          if (err?.status === 404) {
1383	+            this.notFound.set(true);
1384	+          } else {
1385	+            this.error.set(true);
1386	+          }
1387	+        },
1388	+      });
1389	+    });
1390	+  }
1391	+}
